            wt1_D_prev = safe_fetch_float(i.get("wt1_D_prev", i.get("wt2_D")), safe_fetch_float(i.get("wt2_D"), wt1_D))  # 2026-06-03 USER: phantom wt1_X_prev → wt2_X (cross)
