                (wt1_D > _last_wt) if is_long else (wt1_D < _last_wt)
            )
            _hpx_D = (not _req_hpx) or (
                (current_price > _last_px)
                if is_long
                else (current_price < _last_px)
            )
            if _bounce_D and _hwt_D and _hpx_D:
                _triggered_tf = "D"
                _trigger_wt = wt1_D
