            trade_manager._dd_bounce_state[symbol] = {
                "last_aug_ts": time.time(),
                "last_aug_wt": _trigger_wt,
                "last_aug_price": current_price,
                "dd_qty": dd_qty,
            }
            return Signal(
                action="AUGMENT",
                reason=f"DD_BOUNCE_AUG_{_triggered_tf} wt={_trigger_wt:.1f} px={current_price:.4f}>prev={_last_px:.4f} g={gain:.2f}%",
